import json,glob,os,re,collections
files=sorted(glob.glob('.suspense/history/*.json')+glob.glob('.suspense/asks/*.json'),key=os.path.getmtime)[-40:]
linked=0; opened=collections.Counter(); runs_open=0
for f in files:
    d=json.load(open(f))
    up=d.get('userPrompt') or ''
    refs=re.findall(r'\.claude/reference/[^)\s]+\.md',up)
    if refs: linked+=1
    hit=False
    for e in d.get('output',[]):
        if isinstance(e,dict) and e.get('type')=='assistant' and not e.get('parent_tool_use_id'):
            for c in e['message'].get('content',[]):
                if c.get('type')=='tool_use':
                    s=json.dumps(c.get('input'))
                    for m in re.findall(r'\.claude/reference/[A-Za-z0-9_/.-]+\.md',s): opened[m]+=1; hit=True
    runs_open+=hit
print('last',len(files),'runs: prompts containing reference links:',linked,'| runs that opened any reference doc:',runs_open)
for k,v in opened.most_common(8): print(' ',v,k)
